import unittest

from handoff_demo.dispatch import dispatch


class HiddenTests(unittest.TestCase):
    def test_issue_path_reaches_the_affected_behavior(self):
        self.assertEqual(dispatch("receipt", " ab_7 "), "AB-7")
        self.assertEqual(dispatch("receipt", "r-2"), "R-2")
        self.assertEqual(dispatch("receipt", "17"), "17")

    def test_unrelated_components_keep_their_contracts(self):
        self.assertEqual(dispatch("search", "  Foo_BAR  "), "foo_bar")
        self.assertEqual(dispatch("count", "0017"), 17)


if __name__ == "__main__":
    unittest.main()
